# Recover both sets of first crossings from existing calibrated thresholds.
# No bootstrap or Monte Carlo random numbers are generated by this script.
root <- normalizePath(Sys.getenv('JBES_PROJECT_ROOT', getwd()))
for (f in c('00_utils.R', '01_critical_values.R', '02_methods.R', '50_empirical_utils.R'))
  source(file.path(root, f))
jbes_set_root(root)
boot <- read.csv(file.path(root, 'results', 'empirical_bootstrap_check.csv'))
raw <- load_gbpusd_data(Sys.getenv('JBES_GBPUSD_PATH', file.path(root, 'data', 'GBPUSD.csv')))
rows <- list()
for (year in unique(boot$year)) {
  fd <- build_daily_fd(prepare_gbpusd_year(raw, year))
  values <- evaluate_fd_matrix(fd)$values
  configs <- unique(boot[boot$year == year, c('m', 'T', 'gamma')])
  for (i in seq_len(nrow(configs))) {
    cfg <- configs[i, ]; m <- cfg$m; T <- cfg$T; gamma <- cfg$gamma
    score <- compute_empirical_score_matrix(values, fd$dates, m, T)
    asym <- run_empirical_monitoring(score$scores, score$dates, m, T, gamma)
    for (method in c('RSMS', 'SSMS', 'CSMS')) {
      a <- asym[asym$method == method, ]
      b <- boot[boot$year == year & boot$m == m & boot$T == T &
        boot$gamma == gamma & boot$method == method, ]
      stopifnot(
        nrow(b) == 1L, abs(a$statistic - b$statistic) < 1e-7,
        a$reject == b$asymptotic_reject
      )
      k <- first_exceed(
        compute_path(method, score$scores, m, T, gamma),
        b$bootstrap_critical_value
      )
      reject <- k <= m * T
      stopifnot(reject == b$bootstrap_reject)
      rows[[length(rows) + 1L]] <- data.frame(year, m, T, gamma, method,
        d_eff = score$d_eff, statistic = a$statistic,
        asymptotic_critical = a$critical_value, bootstrap_critical = b$bootstrap_critical_value,
        asymptotic_reject = a$reject, bootstrap_reject = reject,
        asymptotic_stop = a$stop_k, bootstrap_stop = k,
        asymptotic_date = a$first_detection_date,
        bootstrap_date = if (reject) as.character(score$dates[m + k]) else NA_character_
      )
    }
  }
}
out <- do.call(rbind, rows)
write.csv(out, file.path(root, 'results', 'empirical_calibration_details.csv'), row.names = FALSE)
cat('Verified', nrow(out), 'empirical method-settings under both calibrations.\n')
